import { getNotificationPreference, toggleNotificationPreference } from './actions'

export default async function Home() {
  // Simulated user ID - in a real app, this would come from authentication
  const userId = 'user-123'

  // Fetch the current notification preference
  const notificationsEnabled = await getNotificationPreference(userId)

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Settings</h1>

      <div style={{ marginTop: '2rem' }}>
        <h2>Notification Preferences</h2>
        <p>
          Notifications are currently: <strong>{notificationsEnabled ? 'ON' : 'OFF'}</strong>
        </p>

        <form action={async () => {
          'use server'
          await toggleNotificationPreference(userId)
        }}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1rem',
              fontSize: '1rem',
              backgroundColor: notificationsEnabled ? '#dc2626' : '#16a34a',
              color: 'white',
              border: 'none',
              borderRadius: '0.375rem',
              cursor: 'pointer'
            }}
          >
            Turn {notificationsEnabled ? 'OFF' : 'ON'}
          </button>
        </form>

        <p style={{ marginTop: '1rem', color: '#666', fontSize: '0.875rem' }}>
          Click the button to toggle your notification preference. The page will refresh automatically to show the updated state.
        </p>
      </div>
    </main>
  )
}

